using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckSumo.Editor {
public static class SumoAuthoring {
 public const string Folder="TruckSumo",Scene="Assets/TruckSumo/Scenes/TruckSumo.unity";
 static readonly List<Vector3> vertices=new List<Vector3>();static readonly List<int> triangles=new List<int>();
 public static void Create(){Directory.CreateDirectory("Assets/"+Folder+"/Models");var m=SportsEventAuthoring.Begin<SumoMatch>(Folder);m.setup.count=4;m.NormalizeSetup();m.feedback.clips=(AudioClip[])LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Clone();m.feedback.clips[5]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Exceptional cheer.wav");var clay=SportsEventAuthoring.Mat(Folder,"Textured sumo clay",new Color(.58f,.37f,.18f),.12f);var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/3D Haven/Path Painter II/Editor/Demo/Terrains/DocsTerrain/TerrainLayers/stdMudRocky.terrainlayer");clay.mainTexture=layer.diffuseTexture;clay.mainTextureScale=Vector2.one*5;var edge=SportsEventAuthoring.Mat(Folder,"Ivory legal outer edge",new Color(.97f,.87f,.58f),.18f);var physics=SportsEventAuthoring.Contact(Folder,"Clay ground",.65f,.04f);var ring=new GameObject("Real shrinking raised clay ring");m.ring=ring.transform;ring.transform.localScale=new Vector3(m.initialRadius,1,m.initialRadius);var mesh=RingMesh();ring.AddComponent<MeshFilter>().sharedMesh=mesh;ring.AddComponent<MeshRenderer>().sharedMaterial=clay;var collider=ring.AddComponent<MeshCollider>();collider.sharedMesh=mesh;collider.sharedMaterial=physics;var rim=TubePart(ring.transform,"Visible legal rim",Enumerable.Range(0,97).Select(i=>new Vector3(Mathf.Sin(i*Mathf.PI*2/96),0,Mathf.Cos(i*Mathf.PI*2/96))).ToArray(),.004f,8,edge);rim.localScale=new Vector3(1,8,1);
  var ground=SportsEventAuthoring.Mat(Folder,"Arena warm stone",new Color(.2f,.23f,.25f),.1f);ground.mainTexture=layer.diffuseTexture;ground.mainTextureScale=Vector2.one*18;SportsEventAuthoring.Box("Surrounding arena floor",new Vector3(0,-2,0),new Vector3(70,.5f,70),ground,physics);
  m.fighters=new SumoFighter[4];for(int i=0;i<4;i++){var truck=SportsEventAuthoring.Truck(m,Folder,"Sumo competitor "+(i+1),new Vector3((i-1.5f)*3,.8f,0),i);SportsRallyAuthoring.FitTruck(truck);truck.maxSpeed=8.5f;truck.reverseSpeed=5;truck.motorTorque=11;truck.brakeTorque=18;truck.steerAngle=48;truck.grip=1.7f;truck.body.mass=12;truck.body.centerOfMass=new Vector3(0,-.15f,0);truck.body.angularDamping=.6f;truck.body.maxAngularVelocity=5;truck.shape.sharedMaterial=SportsEventAuthoring.Contact(Folder,"Fair truck body contact",.22f,.08f);var fighter=truck.gameObject.AddComponent<SumoFighter>();fighter.truck=truck;fighter.match=m;fighter.strain=truck.gameObject.AddComponent<AudioSource>();fighter.strain.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/NWH/Vehicle Physics 2/Sound/GroundNoise/GravelSkidNoise.wav");fighter.strain.playOnAwake=false;fighter.strain.loop=true;Outfit(fighter);m.fighters[i]=fighter;}
  m.broadcast=SportsEventAuthoring.Camera("Sumo stable arena broadcast");m.broadcast.Pose(Vector3.zero,new Vector3(0,15,-26),58,true);m.broadcast.view.orthographic=true;m.broadcast.view.farClipPlane=120;m.fit=m.broadcast.gameObject.AddComponent<SportsCameraFit>();m.fit.cameraTarget=m.broadcast.view;m.fit.arenaFit=true;m.fit.arenaBounds=new Bounds(Vector3.up*.45f,new Vector3(26,2.5f,26));m.fit.topInset=.06f;m.fit.bottomInset=.04f;m.fit.Apply();m.cameras=new[]{m.broadcast.view};m.replay=SportsRallyAuthoring.Replay(m,m.fighters.Select(f=>f.truck.visuals).Concat(new[]{m.ring}).ToArray());m.replay.capacity=1900;m.replay.interval=.05f;
  for(int i=0;i<12;i++){float a=i*Mathf.PI*2/12;var anchor=new GameObject("Installed event dressing "+i).transform;anchor.position=new Vector3(Mathf.Sin(a)*17,-1.7f,Mathf.Cos(a)*17);anchor.rotation=Quaternion.Euler(0,-a*Mathf.Rad2Deg,0);SportsRallyAuthoring.Prop(anchor,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock01_URP.prefab",Vector3.zero,new Vector3(3.5f,.9f,.7f));}
  SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);m.menus.standings.rectTransform.anchoredPosition=new Vector2(-720,325);m.menus.standings.rectTransform.sizeDelta=new Vector2(450,180);SumoPreviewAuthoring.Create(m);SportsEventAuthoring.Save(Folder);Validate();
 }
 static void Outfit(SumoFighter f){var truck=f.truck;var assembly=new GameObject("Sumo render assembly").transform;assembly.SetParent(truck.transform,false);truck.visuals.SetParent(assembly,true);truck.visuals=assembly;var b=truck.paint.bounds;var local=new Bounds(truck.transform.InverseTransformPoint(b.center),Vector3.zero);for(int i=0;i<8;i++)local.Encapsulate(truck.transform.InverseTransformPoint(b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1))));var trim=SportsEventAuthoring.Mat(Folder,"Participant fabric trim",Color.white,.15f);var cloth=SportsEventAuthoring.Mat(Folder,"Mawashi woven charcoal",new Color(.09f,.08f,.1f),.06f);cloth.SetFloat("_Cull",0);var brow=SportsEventAuthoring.Mat(Folder,"Expressive thick eyebrows",new Color(.055f,.025f,.012f),.12f);var painted=new List<Renderer>();float top=local.max.y-.2f,cx=local.center.x,cz=local.center.z,rx=local.extents.x+.035f,rz=local.extents.z+.035f;var band=Enumerable.Range(0,65).Select(i=>new Vector3(cx+rx*Mathf.Sin(i*Mathf.PI*2/64),top,cz+rz*Mathf.Cos(i*Mathf.PI*2/64))).ToArray();var headband=TubePart(assembly,"Fitted forehead headband "+truck.slot,band,.035f,8,trim,2.2f);painted.Add(headband.GetComponent<Renderer>());var belt=Enumerable.Range(0,65).Select(i=>new Vector3(Mathf.Sin(i*Mathf.PI*2/64)*.66f,.08f,Mathf.Cos(i*Mathf.PI*2/64)*.64f)).ToArray();TubePart(assembly,"Curved mawashi belt "+truck.slot,belt,.14f,10,cloth);var seam=TubePart(assembly,"Mawashi participant sewn trim "+truck.slot,belt.Select(v=>v+Vector3.up*.12f).ToArray(),.035f,8,trim);painted.Add(seam.GetComponent<Renderer>());
  f.tails=new Transform[2];for(int side=0;side<2;side++){float sign=side==0?-1:1;var knots=TubePart(assembly,"Bound headband knot "+truck.slot+" "+side,new[]{new Vector3(cx,top,local.min.z-.08f),new Vector3(cx+sign*.13f,top+.05f,local.min.z-.1f),new Vector3(cx+sign*.19f,top-.03f,local.min.z-.1f)},.055f,8,trim);painted.Add(knots.GetComponent<Renderer>());var pivot=new GameObject("Short cloth tail pivot "+side).transform;pivot.SetParent(assembly,false);pivot.localPosition=new Vector3(cx+sign*.12f,top,local.min.z-.09f);f.tails[side]=pivot;var tail=Ribbon(pivot,"Bound cloth tail "+truck.slot+" "+side,new[]{Vector3.zero,new Vector3(sign*.1f,-.16f,-.07f),new Vector3(sign*.18f,-.33f,-.02f)},.09f,trim);painted.Add(tail.GetComponent<Renderer>());}
  for(int side=-1;side<=1;side+=2){Ribbon(assembly,"Mawashi front and rear panel "+truck.slot+" "+side,new[]{new Vector3(0,.18f,side*.64f),new Vector3(0,-.08f,side*.7f),new Vector3(0,-.19f,side*.33f),new Vector3(0,-.12f,0)},.38f,cloth);}
  f.brows=new Transform[2];for(int i=0;i<2;i++){var pivot=new GameObject("Eyebrow expression pivot "+i).transform;pivot.SetParent(assembly,false);pivot.localPosition=new Vector3(cx+(i==0?-1:1)*rx*.48f,top+.11f,local.max.z+.055f);f.brows[i]=pivot;TubePart(pivot,"Rounded expressive brow "+truck.slot+" "+i,Enumerable.Range(0,17).Select(k=>new Vector3(Mathf.Lerp(-rx*.4f,rx*.4f,k/16f),Mathf.Sin(k*Mathf.PI/16)*.04f,0)).ToArray(),.045f,8,brow);}
  f.trim=painted.ToArray();
 }
 static Mesh RingMesh(){vertices.Clear();triangles.Clear();const int n=96;float[] radii={0,.985f,1,1,.97f,0};float[] y={0,0,-.1f,-1,-1.18f,-1.18f};for(int row=0;row<radii.Length;row++)for(int i=0;i<=n;i++){float a=i*Mathf.PI*2/n;vertices.Add(new Vector3(Mathf.Sin(a)*radii[row],y[row],Mathf.Cos(a)*radii[row]));if(row>0&&i<n){int k=row*(n+1)+i;triangles.AddRange(new[]{k,k+1,k-n-1,k+1,k-n,k-n-1});}}return Save("Beveled continuous ring",true);}
 static Transform TubePart(Transform parent,string name,Vector3[] path,float radius,int sides,Material material,float vertical=1){vertices.Clear();triangles.Clear();for(int i=0;i<path.Length;i++){var direction=(path[Mathf.Min(i+1,path.Length-1)]-path[Mathf.Max(0,i-1)]).normalized;var side=Vector3.Cross(direction,Mathf.Abs(direction.y)>.9f?Vector3.forward:Vector3.up).normalized;var up=Vector3.Cross(side,direction).normalized;for(int j=0;j<=sides;j++){float a=j*Mathf.PI*2/sides;vertices.Add(path[i]+radius*(side*Mathf.Cos(a)+up*Mathf.Sin(a)*vertical));if(i>0&&j<sides){int k=i*(sides+1)+j;triangles.AddRange(new[]{k,k+1,k-sides-1,k+1,k-sides,k-sides-1});}}}return Part(parent,name,Save(name,false),material);}
 static Transform Ribbon(Transform parent,string name,Vector3[] centers,float width,Material material){vertices.Clear();triangles.Clear();for(int i=0;i<centers.Length;i++){vertices.Add(centers[i]+Vector3.left*width*.5f);vertices.Add(centers[i]+Vector3.right*width*.5f);if(i>0){int k=i*2;triangles.AddRange(new[]{k-2,k-1,k,k,k-1,k+1});}}return Part(parent,name,Save(name,false),material);}
 static Transform Part(Transform parent,string name,Mesh mesh,Material material){var root=new GameObject(name).transform;root.SetParent(parent,false);root.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;root.gameObject.AddComponent<MeshRenderer>().sharedMaterial=material;return root;}
 static Mesh Save(string name,bool worldUV){var temporary=new Mesh{name=name};temporary.SetVertices(vertices);temporary.SetTriangles(triangles,0);temporary.SetUVs(0,vertices.Select(v=>new Vector2(v.x,v.z)).ToList());temporary.RecalculateNormals();temporary.RecalculateBounds();string path="Assets/"+Folder+"/Models/"+name+".asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){AssetDatabase.CreateAsset(temporary,path);return temporary;}mesh.Clear();mesh.vertices=temporary.vertices;mesh.normals=temporary.normals;mesh.uv=temporary.uv;mesh.triangles=temporary.triangles;mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);UnityEngine.Object.DestroyImmediate(temporary);return mesh;}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<SumoMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<SumoMatch>();}if(m==null||m.fighters.Length!=4||m.ring.GetComponent<MeshCollider>()==null||m.replay.sources.Length!=5||m.feedback.clips.Any(c=>c==null))throw new Exception("Sumo references incomplete");foreach(var fighter in m.fighters)if(fighter.brows.Length!=2||fighter.tails.Length!=2||fighter.truck.body.mass!=12||fighter.truck.visuals.GetComponentsInChildren<Collider>(true).Length!=0)throw new Exception("Sumo fitted cosmetic/fairness contract failed");Debug.Log("SUMO_NATIVE_SCENE_VALIDATED");}
}
}
